        <div class="project-grid">${W.map((d,p)=>`<article class="project-card"><div class="project-number">0${p+1}</div>${ps(d.image_url,d.title||"Project","project-image")}<div class="project-body"><h3>${Le(d.title)}</h3><p>${Le(d.description)}</p><div class="tag-row">${(d.tags||[]).map(g=>`<span>${Le(g)}</span>`).join("")}</div><div class="project-links">${fl("Live",d.live_url)} ${fl("Code",d.repo_url)}</div></div></article>`).join("")}</div>
